code.cpp:
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    int cur = 0, best = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] == 1) cur++;
        else cur = 0;
        best = max(best, cur);
    }
    cout << best << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = sc.nextLong();

        int cur = 0, best = 0;
        for (int i = 0; i < n; i++) {
            if (a[i] == 1) cur++;
            else cur = 0;
            best = Math.max(best, cur);
        }
        System.out.println(best);
    }
}
